hooks.command:
python3 -c "import json,sys,re
d=json.load(sys.stdin)
c=d.get('tool_input',{}).get('command','')
msg=None
if re.search(r'\.env\b(?!\.example)|\.pem\b|id_rsa|\.aws/|\.ssh/|\.config/gcloud/|\.azure/|\.kube/|\.docker/config\.json|\bcredentials?\b(?!\.example|\.sample|\.helper)',c): msg='command references credential material'
if not msg:
    for m in re.finditer(r'\bgit\s+push\b([^;|&]*)',c):
        rest=[t for t in m.group(1).split() if not t.startswith('-')]
        if len(rest)<2 or any(re.search(r'^(main|master)$|[:/](main|master)$',t) for t in rest[1:]):
            msg='bare push or push to the default branch - push an explicit feature branch and open a PR'
            break
if msg: print('Blocked: '+msg,file=sys.stderr)
sys.exit(2 if msg else 0)"
